   !> @param[in]  x      input vector
   !> @param[out] y      result vector
   subroutine nonlocal_pcm_op2_apply(self, trans, x, y)
      !> Operator
      class(nonlocal_pcm_op2), intent(in) :: self
      !> Apply the transpose
      logical, intent(in) :: trans
      !> Input vector
      real(wp), contiguous, intent(in) :: x(:)
